    <?php elseif($pagina==='calendario'): ?>
      <div class="cabecalho-pagina"><div><p class="eyebrow">PROFISSIONAL</p><h1>Calendário mensal</h1><p>Consulte os valores das cobranças por cliente e data de vencimento.</p></div></div>
