    <?php endif; ?>
  </main>
</div>
<script>
document.addEventListener('DOMContentLoaded', function () {
  const modalidade = document.getElementById('modalidade-plano');
  const campoServico = document.querySelector('.campo-servico');
  if (!modalidade || !campoServico) return;
  const seletor = campoServico.querySelector('select');
  const atualizarServico = function () {
    const atividade = modalidade.value === 'por_atividade';
    campoServico.hidden = !atividade;
    if (seletor) seletor.required = atividade;
  };
  modalidade.addEventListener('change', atualizarServico);
  atualizarServico();
});
</script>
</body>
</html>
